#include "stdafx.h"#include "HcdElementBase.h"#include <HcdMemoryService.h>#include <HcdDataTypes_.h>struct SDO_P{#include "PrivateVars/DO.h"};class KDO : public KHcdElementBase  , protected SDO_P{  W_DO *m_pHardware;public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _DO("DO", KDO::Create);IHcdElement *KDO::Create(){  return new KDO;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KDO, 5 )void KDO::InitParm(){#include "PrivateVars/DO.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KDO::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;  m_pHardware = (W_DO*)KMemoryServiceHCD::Instance().IoCreateObj( szName, W_DO::TypeID, domain );  m_pSharedObject = (BYTE*)m_pHardware;  m_pSharedVarsInfo = new SVarInfo;  AddSharedField( "RAW", NULL, offsetof(W_DO, W_DO::RAW), ehtBool, sizeof(tBool), 1 );}void KDO::StepCalc( SStepCalcParams &params ){  if( Invert )    m_pHardware->RAW = OUTR0 = INL0 ? 0 : 1;  else    m_pHardware->RAW = OUTR0 = INL0;}